window.receiveProjectSource({"path": "src/microservices/entity_classification/services/helpers/entity_helpers.py", "lines": ["\"\"\"Helper functions for entity classification entity workflows.\"\"\"", "", "from typing import List, Protocol, Tuple, TypeVar", "from uuid import UUID", "", "from accelerate_models.common.models.enum import AccountType as PlatformAccountType", "from sqlalchemy import func, select", "from sqlalchemy.dialects.postgresql import insert", "from sqlalchemy.ext.asyncio import AsyncSession", "from sqlalchemy.orm import aliased", "", "from common.exceptions import DatabaseReadException", "from common.models.enums import (", "    AccountType,", "    CandidatePromotionTarget,", "    CandidateStatus,", "    EntityType,", ")", "from common.schemas.entities import (", "    Location as LocationSchema,", ")", "from common.schemas.entities import (", "    Locations as LocationsSchema,", ")", "from common.schemas.entities import (", "    Organizations as OrganizationsSchema,", ")", "from common.schemas.entities import (", "    People as PeopleSchema,", ")", "from common.utils.normalize import NORMALIZATION_VERSION, normalize_entity_text", "from microservices.ai_questionnaire.models import EntityResponse", "from microservices.entity_classification.config import config as entity_config", "from microservices.entity_classification.logging import logger", "from microservices.entity_classification.models import (", "    ArticleEntityMap,", "    ArticleIndustry,", "    Location,", "    MatchedEntity,", "    Organization,", "    Person,", ")", "from microservices.entity_classification.schemas import (", "    EntityTypeEnum,", "    MatchedLocation,", "    MatchedOrganizationObj,", "    MatchedPersonObj,", "    OrgContext,", "    PeopleMerged,", ")", "from microservices.entity_classification.schemas.industry_references import IndustryRef", "from microservices.entity_classification.schemas.merged_organizations import OrganizationMerged", "from microservices.entity_classification.schemas.merged_people import PersonMerged", "from microservices.entity_classification.services.helpers import (", "    create_entity_rows,", "    create_industry_rows,", "    create_matched_entity,", "    get_industries,", "    get_industry_defs,", "    merge_organizations_payload,", "    merge_people_payload,", "    process_location,", ")", "from microservices.entity_classification.services.helpers.location_funcs import (", "    build_location_match_candidates,", ")", "from microservices.entity_classification.services.helpers.nvw_match_parsing import (", "    extract_source_refs,", ")", "from microservices.entity_classification.services.helpers.organizations_funcs import (", "    process_organizations_batch,", ")", "from microservices.entity_classification.services.helpers.people_funcs import (", "    process_people_batch,", ")", "from microservices.entity_classification.services.helpers.platform_entity_resolution import (", "    resolve_platform_entity_id_safe,", ")", "from microservices.entity_classification.services.helpers.table_reads import (", "    get_corp_id_by_source_map_batch,", "    get_entity_context_ids_batch,", "    get_entity_source_map_ids_batch,", "    get_master_text_matches_batch,", ")", "from microservices.entity_classification.services.helpers.table_writes import (", "    delete_stale_candidate_observations,", "    update_organization_context,", "    upsert_candidate_observations,", ")", "", "", "async def get_entities_response(", "    db: AsyncSession, article_id: UUID, source_activity_id: UUID", ") -> Tuple[OrganizationsSchema, PeopleSchema, LocationsSchema]:", "    \"\"\"Fetch the three entity_responses rows for a specific AIQ run and parse each into its schema.", "", "    All three reads are anchored to ``source_activity_id`` \u2014 the AIQ", "    ``layer_one_activities.id`` carried on the EC SQS message \u2014 so SQS replays", "    can never combine PEOPLE / ORGANIZATIONS / LOCATIONS payloads from different AIQ runs", "    into one EC pass. AIQ writes all three rows transactionally per run, so within a run", "    a partial result is a contract violation and is raised loudly.", "", "    :param db: Datalake database session (datalake_db).", "    :type db: AsyncSession", "    :param article_id: The article id to fetch entities for.", "    :type article_id: UUID", "    :param source_activity_id: The AIQ ``layer_one_activities.id`` that produced the entities. All three reads are filtered by this value.", "    :type source_activity_id: UUID", "    :return: Organizations, People, and Locations payloads from AIQ.", "    :rtype: Tuple[OrganizationsSchema, PeopleSchema, LocationsSchema]", "    :raises DatabaseReadException: If any of the three entity_responses rows is missing for the run.", "    \"\"\"", "", "    async def _fetch_payload(entity_type: EntityType) -> dict | None:", "        result = await db.execute(", "            select(EntityResponse.validated_response_body)", "            .where(EntityResponse.article_id == article_id)", "            .where(EntityResponse.layer_one_activity_id == source_activity_id)", "            .where(EntityResponse.entity_type == entity_type)", "            .limit(1)", "        )", "        return result.scalars().first()", "", "    payloads: dict[EntityType, dict] = {}", "    for entity_type in (EntityType.PEOPLE, EntityType.ORGANIZATIONS, EntityType.LOCATIONS):", "        payload = await _fetch_payload(entity_type)", "        if payload is not None:", "            payloads[entity_type] = payload", "", "    missing = [", "        t", "        for t in (EntityType.PEOPLE, EntityType.ORGANIZATIONS, EntityType.LOCATIONS)", "        if t not in payloads", "    ]", "    if missing:", "        raise DatabaseReadException(", "            f\"No entity_responses rows for \"", "            f\"article_id={article_id}, source_activity_id={source_activity_id}, \"", "            f\"missing entity_types={[t.value for t in missing]}\"", "        )", "", "    return (", "        OrganizationsSchema.model_validate(payloads[EntityType.ORGANIZATIONS]),", "        PeopleSchema.model_validate(payloads[EntityType.PEOPLE]),", "        LocationsSchema.model_validate(payloads[EntityType.LOCATIONS]),", "    )", "", "", "class _HasEntityText(Protocol):", "    \"\"\"Protocol for objects that expose a textual representation of an entity.", "", "    Attributes:", "        entity_text (str): The entity's text, such as a canonical name or surface form.", "        resolved_corp_id (int | None): CVW corp_id resolved at the matching layer,", "            used by dedup corp-preference. ``None`` when no corp was resolved.", "        match_priority (float | None): The match's ``nvw_match.categories.priority``", "            (lower = more specific). ``None`` when the match is uncategorized. Drives", "            lowest-wins selection when one (name, corp) has several matches.", "    \"\"\"", "", "    entity_text: str", "    resolved_corp_id: int | None", "    match_priority: float | None", "", "", "_MatchedEntityT = TypeVar(\"_MatchedEntityT\", bound=_HasEntityText)", "", "# Sentinel for an uncategorized match (``match_priority`` is ``None``) in lowest-wins", "# dedup: it must lose to any categorized match. Mirrors build_doc_entity_reasons'", "# _DEFAULT_PRIORITY so the two stages agree on which row is \"most specific\".", "_MISSING_MATCH_PRIORITY: float = 999.0", "", "", "def _sort_priority(match_obj: _HasEntityText) -> float:", "    \"\"\"Comparable priority for lowest-wins dedup; ``None`` maps to the worst value.", "", "    :param match_obj: A matched-entity object exposing ``match_priority``.", "    :type match_obj: _HasEntityText", "    :return: ``match_priority`` if set, else ``_MISSING_MATCH_PRIORITY``.", "    :rtype: float", "    \"\"\"", "    priority = match_obj.match_priority", "    return priority if priority is not None else _MISSING_MATCH_PRIORITY", "", "", "def _dedupe_matches_by_normalized_name(", "    match_objs: List[_MatchedEntityT],", ") -> List[_MatchedEntityT]:", "    \"\"\"Deduplicate matched entities per (normalized name, corp_id), keeping every corp.", "", "    A single extracted name can legitimately resolve to MORE THAN ONE corp \u2014 e.g. a", "    subsidiary row pointing at the parent's corp AND the company's own dedicated entity", "    corp. Each distinct corp must keep a match so it gets its own CVW attribution, so", "    deduplication is keyed on ``(normalize_entity_text(entity_text), resolved_corp_id)``", "    rather than on the normalized name alone.", "", "    Within one normalized name:", "      - Each distinct ``resolved_corp_id`` keeps its lowest-``match_priority`` (most", "        specific) match; same-name + same-corp duplicates collapse onto it. Lowest-wins", "        rather than first-seen because ``get_master_text_matches_batch`` returns matches", "        in no deterministic order \u2014 keeping first-seen could drop an Entity row", "        (priority 20) in favour of a Subsidiary row (priority 40) for the same corp,", "        which then breaks the Entity-beats-Subsidiary guarantee build_doc_entity_reasons", "        relies on. Ties keep the first-seen match.", "      - A non-corp match (``resolved_corp_id`` is ``None``) is kept only when NO", "        corp-bearing match shares its normalized name \u2014 preserving the", "        corp-bearing-over-same-name-non-corp preference (a name matching both a", "        corp-bearing ``pio.entity_master`` entity and an ``ind_vw.accounts``", "        industry-account entity keeps only the corp match) without emitting spurious", "        non-corp matches. At most one non-corp match (the lowest-priority one) survives", "        per such name.", "", "    Args:", "        match_objs: A list of matched-entity objects, each providing an 'entity_text'", "            string, a 'resolved_corp_id' (``None`` when no corp resolved), and a", "            'match_priority' (``None`` when uncategorized).", "", "    Returns:", "        A new list with one match per distinct (normalized name, corp_id), plus at most", "        one non-corp match per normalized name that has no corp-bearing match. Order", "        follows first-occurrence of each surviving key. Input objects are not modified.", "    \"\"\"", "    normalize = normalize_entity_text", "    # Names with at least one corp-bearing match \u2014 lets the single forward pass drop a", "    # same-name non-corp match (corp-bearing preference) without a second reconciliation.", "    names_with_corp = {", "        normalize(m.entity_text) for m in match_objs if m.resolved_corp_id is not None", "    }", "    # Best (lowest-priority) match per key, in first-occurrence-of-key order (dict", "    # preserves insertion order; only a strictly-lower-priority row replaces the value,", "    # so a tie keeps first-seen and the key's position never moves).", "    best_by_key: dict[tuple[str, int | None], _MatchedEntityT] = {}", "    for match_obj in match_objs:", "        norm_name = normalize(match_obj.entity_text)", "        corp_id = match_obj.resolved_corp_id", "        if corp_id is None and norm_name in names_with_corp:", "            continue  # corp-bearing match for this name wins; drop the non-corp one", "        key = (norm_name, corp_id)", "        existing = best_by_key.get(key)", "        if existing is None or _sort_priority(match_obj) < _sort_priority(existing):", "            best_by_key[key] = match_obj", "    return list(best_by_key.values())", "", "", "async def match_people(", "    db: AsyncSession,", "    master_db: AsyncSession,", "    accelerate_db: AsyncSession,", "    people: PeopleSchema,", "    article_id: UUID,", "    activity_id: UUID | None = None,", ") -> Tuple[List[MatchedPersonObj], List[IndustryRef]]:", "    \"\"\"Deduplicate people payloads, match against master text, and create EC rows.", "", "    :param db: Datalake database session (datalake_db).", "    :type db: AsyncSession", "    :param master_db: Master database session (master_db) for read-only lookups.", "    :type master_db: AsyncSession", "    :param accelerate_db: Accelerate database session. Accepted for symmetry", "        with match_orgs/match_locations/write_matched_industries; person", "        matched_entity rows are never stamped with platform_entity_id (XVW", "        deferred), so this session is forwarded but never queried here.", "    :type accelerate_db: AsyncSession", "    :param people: Extracted people payload.", "    :type people: PeopleSchema", "    :param article_id: The associated article ID.", "    :type article_id: UUID", "    :return: Matched people objects and industry refs.", "    :rtype: Tuple[List[MatchedPersonObj], List[IndustryRef]]", "    \"\"\"", "    del accelerate_db  # symmetry only \u2014 see docstring", "    # 1). Merge people llm-chat payload \u2014 a single normalized-name-keyed pass", "    # consolidates duplicate person entries (canonical raw spelling = first seen,", "    # is_owner OR-combined, evidence deduped by text). No second dedup pass.", "    merged_people: PeopleMerged = merge_people_payload(people)", "    deduped_people: dict[str, PersonMerged] = dict(merged_people.root)", "", "    # 2). Batch-fetch all master text matches, context IDs, and source map IDs.", "    #     Pass RAW names \u2014 the batch reader normalizes both sides and keys results", "    #     on the normalized value, so process_people_batch retrieves via", "    #     normalize_entity_text(full_name). This is the single caller contract", "    #     shared with match_orgs / build_location_match_map.", "    all_names = list(deduped_people.keys())", "    all_entries = list(deduped_people.values())", "", "    matches_by_text = await get_master_text_matches_batch(master_db, all_names)", "", "    # 3). Collect all entity_ids from matches for batch context/source_map lookups", "    all_entity_ids: set[int] = set()", "    for matches_list in matches_by_text.values():", "        for match in matches_list:", "            all_entity_ids.add(match[\"xref\"].entity_id)", "", "    context_ids = await get_entity_context_ids_batch(master_db, all_entity_ids)", "    source_map_ids = await get_entity_source_map_ids_batch(master_db, all_entity_ids)", "", "    # 3b). Broad source-map corp signal (any pio_id source row), used only as the", "    # corp-preference fallback so a person whose corp signal (officer/CEO company) comes", "    # via a source-map row is not dropped for a same-name non-corp match. People rows are", "    # never stamped with platform_entity_id.", "    source_map_id_set = {smid for smid in source_map_ids.values() if smid is not None}", "    any_corp_id_by_source_map_id = await get_corp_id_by_source_map_batch(", "        master_db, source_map_id_set", "    )", "", "    # 4). Process all people using pre-fetched data (no per-person DB queries)", "    ent_rows: List[Person] = []", "    match_objs: List[MatchedPersonObj] = []", "    industry_refs: List[IndustryRef] = []", "    try:", "        # (a). Process people in batch, creating entity rows and collecting match info for industry refs", "        (", "            ent_rows,", "            per_person_me,", "            industry_refs,", "            per_person_resolved_corp,", "        ) = await process_people_batch(", "            db,", "            all_names,", "            all_entries,", "            article_id,", "            matches_by_text,", "            context_ids,", "            source_map_ids,", "            any_corp_id_by_source_map_id,", "            activity_id=activity_id,", "        )", "", "        # (b). Build MatchedPersonObj list using the same ordering as input names", "        for full_name, entry, me_rows, resolved_corp in zip(", "            all_names, all_entries, per_person_me, per_person_resolved_corp, strict=True", "        ):", "            for me_row, (resolved_corp_id, resolved_source_table) in zip(", "                me_rows, resolved_corp, strict=True", "            ):", "                # Each obj carries ITS match's priority via a per-match copy; a shared", "                # `entry` would leak the last match's priority across all corps' reasons.", "                match_objs.append(", "                    MatchedPersonObj(", "                        entity_text=full_name,", "                        entity_type=EntityTypeEnum.PERSON,", "                        person_raw_data=entry.model_copy(", "                            update={\"priority\": me_row.category_priority}", "                        ),", "                        entity_source_map_id=me_row.entity_source_map_id,", "                        resolved_corp_id=resolved_corp_id,", "                        resolved_source_table=resolved_source_table,", "                    )", "                )", "    except Exception as e:", "        logger.error(", "            \"Error while batch-processing people\",", "            article_id=article_id,", "            _exc=e,", "        )", "", "    # 5). Create all entity rows in a single batch insert", "    await create_entity_rows(db, ent_rows)", "", "    return _dedupe_matches_by_normalized_name(match_objs), industry_refs", "", "", "async def match_orgs(", "    db: AsyncSession,", "    master_db: AsyncSession,", "    accelerate_db: AsyncSession,", "    orgs: OrganizationsSchema,", "    article_id: UUID,", "    activity_id: UUID | None = None,", ") -> Tuple[List[MatchedOrganizationObj], List[IndustryRef]]:", "    \"\"\"Deduplicate organization payloads, match against master text, and create EC rows.", "", "    Pre-computes the broad source-map corp signal (``any_corp_id_by_source_map_id``)", "    from master_db and passes it into ``process_organizations_batch``, which resolves", "    each org's corp_id (original_id \u222a source-map) and stamps the canonical", "    platform_entity_id against accelerate \u2014 for any corp-bearing provenance, not only", "    ``cvw.corporations`` source-map rows.", "", "    :param db: Datalake database session (datalake_db).", "    :type db: AsyncSession", "    :param master_db: Master database session (master_db) for read-only lookups.", "    :type master_db: AsyncSession", "    :param accelerate_db: Accelerate database session for canonical platform_entity_id resolution.", "    :type accelerate_db: AsyncSession", "    :param orgs: Extracted organizations payload.", "    :type orgs: OrganizationsSchema", "    :param article_id: The associated article ID.", "    :type article_id: UUID", "    :return: Matched organization objects and industry refs.", "    :rtype: Tuple[List[MatchedOrganizationObj], List[IndustryRef]]", "    \"\"\"", "    # 1). Merge organizations llm-chat payload \u2014 a single normalized-name-keyed", "    # pass consolidates duplicate org entries (canonical raw spelling = first", "    # seen, organization_type COMPANY->non-COMPANY upgrade, org_type_evidence", "    # fill-if-missing, evidence deduped by text). No second dedup pass.", "    merged_orgs = merge_organizations_payload(orgs)", "    deduped_orgs: dict[str, OrganizationMerged] = dict(merged_orgs.root)", "", "    # 2). Batch-fetch all master text matches, context IDs, and source map IDs", "    all_names = list(deduped_orgs.keys())", "    all_entries = list(deduped_orgs.values())", "", "    matches_by_text = await get_master_text_matches_batch(master_db, all_names)", "", "    # 3). Collect all entity_ids from matches for batch context/source_map lookups", "    all_entity_ids: set[int] = set()", "    for matches_list in matches_by_text.values():", "        for match in matches_list:", "            all_entity_ids.add(match[\"xref\"].entity_id)", "", "    context_ids = await get_entity_context_ids_batch(master_db, all_entity_ids)", "    source_map_ids = await get_entity_source_map_ids_batch(master_db, all_entity_ids)", "", "    # 3b). Broad source-map corp signal (any pio_id source row, e.g. off_brd.subsidiaries,", "    # sec.cik_matches). Drives both the platform_entity_id stamp and the dedup", "    # corp-preference. ind_vw.* has no pio_id column so it never appears here; a corp_id", "    # with no ent.entities bridge row resolves to NULL and stays unstamped.", "    source_map_id_set = {smid for smid in source_map_ids.values() if smid is not None}", "    any_corp_id_by_source_map_id = await get_corp_id_by_source_map_batch(", "        master_db, source_map_id_set", "    )", "", "    # 4). Process all organizations using pre-fetched data (no per-org DB queries)", "    ent_rows: List[Organization] = []", "    match_objs: List[MatchedOrganizationObj] = []", "    industry_refs: List[IndustryRef] = []", "    try:", "        # (a). Process orgs in batch, creating entity rows and collecting match info for industry refs", "        (", "            ent_rows,", "            per_org_me,", "            industry_refs,", "            per_org_resolved_corp,", "        ) = await process_organizations_batch(", "            db,", "            accelerate_db,", "            all_names,", "            all_entries,", "            article_id,", "            matches_by_text,", "            context_ids,", "            source_map_ids,", "            any_corp_id_by_source_map_id,", "            activity_id=activity_id,", "        )", "", "        # (b). Build MatchedOrganizationObj list using the same ordering as input names", "        for org_name, entry, me_rows, resolved_corp in zip(", "            all_names, all_entries, per_org_me, per_org_resolved_corp, strict=True", "        ):", "            for me_row, (resolved_corp_id, resolved_source_table) in zip(", "                me_rows, resolved_corp, strict=True", "            ):", "                # Each obj carries ITS match's priority via a per-match copy; a shared", "                # `entry` would leak the last match's priority across all corps' reasons.", "                match_objs.append(", "                    MatchedOrganizationObj(", "                        entity_text=org_name,", "                        entity_type=EntityTypeEnum.ORGANIZATION,", "                        organization_raw_data=entry.model_copy(", "                            update={\"priority\": me_row.category_priority}", "                        ),", "                        entity_source_map_id=me_row.entity_source_map_id,", "                        resolved_corp_id=resolved_corp_id,", "                        resolved_source_table=resolved_source_table,", "                    )", "                )", "    except Exception as e:", "        logger.error(", "            \"Error while batch-processing organizations\",", "            article_id=article_id,", "            _exc=e,", "        )", "", "    # 5). Create all entity rows in a single batch insert", "    await create_entity_rows(db, ent_rows)", "", "    return _dedupe_matches_by_normalized_name(match_objs), industry_refs", "", "", "async def match_locations(", "    db: AsyncSession,", "    master_db: AsyncSession,", "    accelerate_db: AsyncSession,", "    locations: LocationsSchema,", "    article_id: UUID,", "    activity_id: UUID | None = None,", ") -> Tuple[List[MatchedLocation], List[IndustryRef], List[dict]]:", "    \"\"\"Persist location items and attempt master-data matches for industries.", "", "    :param db: Datalake database session (datalake_db).", "    :type db: AsyncSession", "    :param master_db: Master database session (master_db) for read-only lookups.", "    :type master_db: AsyncSession", "    :param accelerate_db: Accelerate database session for platform_entity_id resolution.", "    :type accelerate_db: AsyncSession", "    :param locations: Extracted locations payload.", "    :type locations: LocationsSchema", "    :param article_id: The associated article ID.", "    :type article_id: UUID", "    :return: Matched location info, industry refs, and any skipped location items.", "    :rtype: Tuple[List[MatchedLocation], List[IndustryRef], List[dict]]", "    \"\"\"", "    matches: List[MatchedLocation] = []", "    loc_rows: List[Location] = []", "    industry_refs: List[IndustryRef] = []", "    skipped_locations: List[dict] = []", "    for location in locations.items:", "        try:", "            loc_row, match_info = await process_location(", "                db, master_db, accelerate_db, location, article_id, activity_id=activity_id", "            )", "            loc_rows.append(loc_row)", "            matches.append(match_info)", "            refs = await match_location_to_master(db, master_db, location, article_id, activity_id)", "            # Commit each location's matched_entity writes before the next, so a later", "            # location's rollback can't orphan refs and no txn spans the next resolver call.", "            await db.commit()", "            industry_refs.extend(refs)", "        except Exception as e:", "            # Clear the pending-rollback session so this location's failure can't cascade", "            # into later locations or the trailing flush; prior locations are committed.", "            await db.rollback()", "            logger.error(", "                \"Error while processing location; skipping\",", "                article_id=article_id,", "                location=location,", "                _exc=e,", "            )", "            skipped_locations.append({\"location\": str(location), \"error\": repr(e)})", "            continue", "", "    await create_entity_rows(db, loc_rows)", "    return matches, industry_refs, skipped_locations", "", "", "async def write_article_entity_map(", "    db: AsyncSession,", "    article_id: UUID,", "    matched_people: List[MatchedPersonObj],", "    matched_orgs: List[MatchedOrganizationObj],", "    matched_locs: List[MatchedLocation],", "    industry_refs: List[IndustryRef],", "    article_industries: List[ArticleIndustry],", "    activity_id: UUID | None = None,", "    feed_market_ids: list[int] | None = None,", ") -> set[AccountType]:", "    \"\"\"Create missing ArticleEntityMap rows for this article and return account types.", "", "    :param db: Datalake database session (datalake_db).", "    :type db: AsyncSession", "    :param article_id: The associated article ID.", "    :type article_id: UUID", "    :param matched_people: Matched people objects.", "    :type matched_people: List[MatchedPersonObj]", "    :param matched_orgs: Matched organization objects.", "    :type matched_orgs: List[MatchedOrganizationObj]", "    :param matched_locs: Matched location objects.", "    :type matched_locs: List[MatchedLocation]", "    :param industry_refs: Industry refs from matching for IVW.", "    :type industry_refs: List[IndustryRef]", "    :param article_industries: Pre-fetched ArticleIndustry rows from write_matched_industries.", "    :type article_industries: List[ArticleIndustry]", "    :param feed_market_ids: Market IDs from feed_markets config (baseline MVW coverage).", "    :type feed_market_ids: list[int] | None", "    :return: Account types written or already present.", "    :rtype: set[AccountType]", "    \"\"\"", "    entity_types: set[AccountType] = set()", "    evidence_by_type: dict[AccountType, dict] = {}", "    meta_by_type: dict[AccountType, dict] = {}", "", "    # CVW \u2014 only include keys that have data.", "    if matched_people or matched_orgs:", "        cvw_evidence: dict[str, list] = {}", "        cvw_meta: dict[str, int] = {}", "        if matched_people:", "            people_names = [p.entity_text for p in matched_people]", "            cvw_evidence[\"people\"] = people_names", "            cvw_meta[\"people_count\"] = len(people_names)", "        if matched_orgs:", "            org_names = [o.entity_text for o in matched_orgs]", "            cvw_evidence[\"organizations\"] = org_names", "            cvw_meta[\"organization_count\"] = len(org_names)", "        entity_types.add(AccountType.CVW)", "        evidence_by_type[AccountType.CVW] = cvw_evidence", "        meta_by_type[AccountType.CVW] = cvw_meta", "", "    # MVW \u2014 locations tied to a market or feed-level market config.", "    matched_market_locs = [loc for loc in matched_locs if loc.matched_market_ids]", "    if matched_market_locs or feed_market_ids:", "        evidence_by_type[AccountType.MVW] = {", "            \"locations\": [", "                {", "                    \"city\": loc.city,", "                    \"region\": loc.region,", "                    \"state\": loc.state.value if hasattr(loc.state, \"value\") else loc.state,", "                    \"matched_market_ids\": loc.matched_market_ids,", "                }", "                for loc in matched_market_locs", "            ],", "            \"feed_market_ids\": feed_market_ids or [],", "        }", "        meta_by_type[AccountType.MVW] = {", "            \"location_count\": len(matched_market_locs),", "            \"feed_market_count\": len(feed_market_ids or []),", "        }", "        entity_types.add(AccountType.MVW)", "", "    # IVW \u2014 gate on actual written rows, not raw refs (refs may be filtered", "    # during write_matched_industries when the industry_id is missing).", "    if article_industries:", "        industries = [", "            {", "                \"industry_id\": row.industry_id,", "                \"industry_name\": row.industry_name,", "            }", "            for row in article_industries", "        ]", "        evidence_by_type[AccountType.IVW] = {\"industries\": industries}", "        meta_by_type[AccountType.IVW] = {\"industry_count\": len(industries)}", "        entity_types.add(AccountType.IVW)", "", "    # Short-circuit if nothing applies.", "    if not entity_types:", "        return set()", "", "    # Upsert each entity type \u2014 atomic via UNIQUE(article_id, entity_type).", "    for etype in entity_types:", "        values = {", "            \"article_id\": article_id,", "            \"entity_type\": etype,", "            \"evidence\": evidence_by_type.get(etype),", "            \"metadata\": meta_by_type.get(etype),", "            \"layer_one_activity_id\": activity_id,", "        }", "        # Use the table object so column keys (\"metadata\") are treated as SQL columns,", "        # not ORM attribute names (which would collide with DeclarativeBase.metadata).", "        stmt = insert(ArticleEntityMap.__table__).values(**values)", "        stmt = stmt.on_conflict_do_update(", "            constraint=\"article_entity_map_article_entity_type_ukey\",", "            set_={", "                \"evidence\": stmt.excluded.evidence,", "                \"metadata\": stmt.excluded.metadata,", "                \"updated_at\": func.now(),", "            },", "        )", "        await db.execute(stmt)", "", "    await db.flush()", "", "    return entity_types", "", "", "def _compose_person_name(first: str | None, middle: str | None, last: str | None) -> str:", "    \"\"\"Join a person's name parts into a single display string.", "", "    :param first: First name.", "    :param middle: Middle initial or fragment.", "    :param last: Last name.", "    :return: Space-joined name with empty parts dropped.", "    :rtype: str", "    \"\"\"", "    return \" \".join(part for part in (first, middle, last) if part)", "", "", "def _compose_location_name(city: str | None, region: str | None, state: str | None) -> str:", "    \"\"\"Join a location's components into a single display string.", "", "    The ``Location`` model has no ``name`` column, so a co-occurring location", "    ref composes one from its non-empty components.", "", "    :param city: City name.", "    :param region: Region / county.", "    :param state: State / province.", "    :return: Comma-joined location string with empty parts dropped.", "    :rtype: str", "    \"\"\"", "    return \", \".join(part for part in (city, region, state) if part)", "", "", "async def assemble_and_write_org_context(", "    db: AsyncSession,", "    article_id: UUID,", "    activity_id: UUID | None,", "    article_industries: List[ArticleIndustry],", ") -> None:", "    \"\"\"Assemble per-org surrounding context and stamp it onto each org row.", "", "    Runs after all entity dimensions are computed (people, orgs, locations,", "    industries, article_entity_map). Does ONE bulk read of the article's", "    committed ``Organization`` / ``Person`` / ``Location`` rows for the", "    activity, with an explicit LEFT JOIN to ``MatchedEntity`` for the org's", "    canonical ``platform_entity_id`` (never traversing the ``lazy=\"raise\"``", "    relationships), then writes each org's ``context`` via a bounded set of", "    UPDATEs. The write is NOT committed here \u2014 the caller's end-of-pipeline", "    commit persists it.", "", "    Each processed org always receives an OBJECT (``type_hint`` + arrays);", "    absent dimensions are empty arrays. NULL ``context`` is reserved for", "    historical rows and the fail-safe failure path. Every id in the JSON is a", "    string or ``None`` (JSONB serialization safety); ``type_hint`` is", "    ``org_type.value`` (a string), never the ``OrganizationType`` enum. Persons", "    are never stamped with a ``platform_entity_id``. The assembled payload is", "    validated and re-emitted through :class:`OrgContext` (the published read", "    contract) so the writer and contract cannot drift.", "", "    :param db: Datalake database session (datalake_db).", "    :type db: AsyncSession", "    :param article_id: The associated article ID.", "    :type article_id: UUID", "    :param activity_id: EC layer-one activity UUID scoping the entity rows.", "    :type activity_id: UUID | None", "    :param article_industries: ArticleIndustry rows written for this article.", "    :type article_industries: List[ArticleIndustry]", "    :return: None", "    :rtype: None", "    \"\"\"", "    # 1). Read the article's org rows first and bail before the other reads when", "    #     there is nothing to stamp. LEFT JOIN MatchedEntity for the org's", "    #     canonical platform_entity_id (never via lazy=\"raise\" traversal).", "    org_me = aliased(MatchedEntity)", "    org_rows = (", "        await db.execute(", "            select(", "                Organization.id,", "                Organization.name,", "                Organization.org_type,", "                Organization.matched_entity_id,", "                org_me.platform_entity_id,", "            )", "            .outerjoin(org_me, Organization.matched_entity_id == org_me.id)", "            .where(", "                Organization.article_id == article_id,", "                Organization.layer_one_activity_id == activity_id,", "            )", "        )", "    ).all()", "", "    if not org_rows:", "        return", "", "    # Persons are never stamped with a platform_entity_id \u2014 no MatchedEntity join.", "    person_rows = (", "        await db.execute(", "            select(", "                Person.id,", "                Person.first_name,", "                Person.middle_initial,", "                Person.last_name,", "                Person.matched_entity_id,", "            ).where(", "                Person.article_id == article_id,", "                Person.layer_one_activity_id == activity_id,", "            )", "        )", "    ).all()", "", "    loc_rows = (", "        await db.execute(", "            select(", "                Location.id,", "                Location.city,", "                Location.region,", "                Location.state,", "                Location.platform_entity_id,", "            ).where(", "                Location.article_id == article_id,", "                Location.layer_one_activity_id == activity_id,", "            )", "        )", "    ).all()", "", "    # 2). Article-level dimensions shared across every org on the article.", "    article_geography = [", "        {\"city\": row.city, \"region\": row.region, \"state\": row.state} for row in loc_rows", "    ]", "    industries = [", "        {", "            \"industry_id\": ind.industry_id,", "            \"industry_name\": ind.industry_name,", "            \"platform_entity_id\": str(ind.platform_entity_id) if ind.platform_entity_id else None,", "            \"matched_entity_ids\": [str(meid) for meid in (ind.matched_entity_ids or [])],", "        }", "        for ind in article_industries", "    ]", "", "    # 3). Co-occurring refs for non-org entities (shared) plus per-org neighbors.", "    person_refs = [", "        {", "            \"type\": \"person\",", "            \"id\": str(row.id),", "            \"name\": _compose_person_name(row.first_name, row.middle_initial, row.last_name),", "            \"matched_entity_id\": str(row.matched_entity_id) if row.matched_entity_id else None,", "        }", "        for row in person_rows", "    ]", "    location_refs = [", "        {", "            \"type\": \"location\",", "            \"id\": str(row.id),", "            \"name\": _compose_location_name(row.city, row.region, row.state),", "            \"platform_entity_id\": str(row.platform_entity_id) if row.platform_entity_id else None,", "        }", "        for row in loc_rows", "    ]", "    org_refs_by_id = {", "        row.id: {", "            \"type\": \"organization\",", "            \"id\": str(row.id),", "            \"name\": row.name,", "            \"matched_entity_id\": str(row.matched_entity_id) if row.matched_entity_id else None,", "            \"platform_entity_id\": str(row.platform_entity_id) if row.platform_entity_id else None,", "        }", "        for row in org_rows", "    }", "", "    # 4). Build each org's context object; co_occurring_entities excludes self.", "    context_by_org_name: dict[str, dict] = {}", "    for row in org_rows:", "        other_org_refs = [ref for oid, ref in org_refs_by_id.items() if oid != row.id]", "        context_by_org_name[row.name] = OrgContext.model_validate(", "            {", "                \"type_hint\": row.org_type.value if row.org_type is not None else None,", "                \"article_geography\": list(article_geography),", "                \"industries\": list(industries),", "                \"co_occurring_entities\": other_org_refs + person_refs + location_refs,", "            }", "        ).model_dump(mode=\"json\")", "", "    await update_organization_context(db, article_id, activity_id, context_by_org_name)", "", "", "async def write_org_context_failsafe(", "    db: AsyncSession,", "    article_id: UUID,", "    activity_id: UUID | None,", "    article_industries: List[ArticleIndustry],", ") -> None:", "    \"\"\"Assemble + stamp per-org context inside a SAVEPOINT; never break extraction.", "", "    Wraps :func:`assemble_and_write_org_context` in ``begin_nested()`` so a", "    failure rolls back only the context write \u2014 leaving ``context`` NULL and the", "    surrounding transaction usable for the end-of-pipeline commit. Context is", "    additive and unread, so any error is logged at warning and swallowed. A bare", "    ``try/except`` would be insufficient: a failed statement aborts the whole", "    transaction, breaking the later commit.", "", "    :param db: Datalake database session (datalake_db).", "    :type db: AsyncSession", "    :param article_id: The associated article ID.", "    :type article_id: UUID", "    :param activity_id: EC layer-one activity UUID scoping the entity rows.", "    :type activity_id: UUID | None", "    :param article_industries: ArticleIndustry rows written for this article.", "    :type article_industries: List[ArticleIndustry]", "    :return: None", "    :rtype: None", "    \"\"\"", "    try:", "        async with db.begin_nested():", "            await assemble_and_write_org_context(db, article_id, activity_id, article_industries)", "    except Exception as exc:", "        logger.warning(", "            \"Failed to assemble organization context; leaving context NULL\",", "            article_id=article_id,", "            activity_id=activity_id,", "            exc_class=type(exc).__name__,", "            _exc=exc,", "        )", "", "", "def _candidate_geography(context: dict | None) -> str | None:", "    \"\"\"Compose the rollup's representative geography from the first ``context['article_geography']`` entry; returns ``None`` when the context carries no usable location.", "", "    :param context: The source org's ``context`` JSONB (may be ``None``).", "    :type context: dict | None", "    :return: A composed \"city, region, state\" string, or ``None``.", "    :rtype: str | None", "    \"\"\"", "    if not isinstance(context, dict):", "        return None", "    geographies = context.get(\"article_geography\")", "    if not isinstance(geographies, list) or not geographies:", "        return None", "    first = geographies[0]", "    if not isinstance(first, dict):", "        return None", "    # Only string parts compose; a malformed non-string coerces to None (NULL geography).", "    city = first.get(\"city\")", "    region = first.get(\"region\")", "    state = first.get(\"state\")", "    composed = _compose_location_name(", "        city if isinstance(city, str) else None,", "        region if isinstance(region, str) else None,", "        state if isinstance(state, str) else None,", "    )", "    return composed or None", "", "", "async def assemble_and_write_candidate_observations(", "    db: AsyncSession,", "    article_id: UUID,", "    activity_id: UUID | None,", ") -> None:", "    \"\"\"Capture each unmatched org sighting as a candidate observation.", "", "    Runs after the org rows are persisted (they were committed by", "    ``create_entity_rows``) and after the step-6b context write. Does ONE bulk read", "    of this article/activity's persisted ``Organization`` rows where", "    ``matched_entity_id IS NULL`` on the same ``self.db`` session (same-session is", "    required because the step-6b ``context`` UPDATE is still uncommitted \u2014 only this", "    transaction sees it), builds one candidate per unmatched org, upserts them on", "    the activity-scoped natural key, then removes stale candidates whose source org", "    is no longer unmatched. The write is NOT committed here \u2014 the caller's", "    end-of-pipeline commit persists it.", "", "    Only ``matched_entity_id IS NULL`` rows are captured: an org that matched a", "    non-canonical row carries a non-NULL id and is excluded.", "", "    :param db: Datalake database session (datalake_db).", "    :type db: AsyncSession", "    :param article_id: The associated article ID.", "    :type article_id: UUID", "    :param activity_id: EC layer-one activity UUID scoping the org rows.", "    :type activity_id: UUID | None", "    :return: None", "    :rtype: None", "    \"\"\"", "    # 1). Read this article/activity's persisted unmatched org rows (same session:", "    #     the step-6b context UPDATE is uncommitted, so only this txn sees it).", "    unmatched_rows = (", "        await db.execute(", "            select(", "                Organization.id,", "                Organization.article_id,", "                Organization.layer_one_activity_id,", "                Organization.name,", "                Organization.org_type,", "                Organization.evidence,", "                Organization.context,", "            ).where(", "                Organization.article_id == article_id,", "                Organization.layer_one_activity_id == activity_id,", "                Organization.matched_entity_id.is_(None),", "            )", "        )", "    ).all()", "", "    # 2). article_id / layer_one_activity_id are the org row's natural key;", "    #     organization_id is the provenance link back to the sighting.", "    candidates = [", "        {", "            \"article_id\": row.article_id,", "            \"layer_one_activity_id\": row.layer_one_activity_id,", "            \"organization_id\": row.id,", "            \"name\": row.name,", "            \"normalized_name\": normalize_entity_text(row.name),", "            \"normalization_version\": NORMALIZATION_VERSION,", "            \"type_hint\": row.org_type,", "            \"geography\": _candidate_geography(row.context),", "            \"evidence\": row.evidence,", "            \"context\": row.context,", "            \"status\": CandidateStatus.NEW,", "            \"promotion_target\": CandidatePromotionTarget.NONE,", "        }", "        for row in unmatched_rows", "    ]", "", "    # 3). Upsert the current unmatched set (no commit).", "    await upsert_candidate_observations(db, candidates)", "", "    # 4). Reconcile: drop candidates in scope whose source org flipped to matched on", "    #     a same-activity retry (scoped to this article/activity only).", "    current_org_ids = [row.id for row in unmatched_rows]", "    await delete_stale_candidate_observations(db, article_id, activity_id, current_org_ids)", "", "", "async def write_candidate_observations_failsafe(", "    db: AsyncSession,", "    article_id: UUID,", "    activity_id: UUID | None,", ") -> None:", "    \"\"\"Capture candidate observations inside a SAVEPOINT; never break extraction.", "", "    Wraps :func:`assemble_and_write_candidate_observations` in ``begin_nested()`` so", "    a failure rolls back only the candidate write \u2014 leaving the surrounding", "    transaction usable for the end-of-pipeline commit. Candidates are additive and", "    off the matching/attribution path, so any error is logged at warning and", "    swallowed. A bare ``try/except`` would be insufficient: a failed statement", "    aborts the whole transaction, breaking the later commit.", "", "    :param db: Datalake database session (datalake_db).", "    :type db: AsyncSession", "    :param article_id: The associated article ID.", "    :type article_id: UUID", "    :param activity_id: EC layer-one activity UUID scoping the org rows.", "    :type activity_id: UUID | None", "    :return: None", "    :rtype: None", "    \"\"\"", "    try:", "        async with db.begin_nested():", "            await assemble_and_write_candidate_observations(db, article_id, activity_id)", "    except Exception as exc:", "        logger.warning(", "            \"Failed to write candidate observations; skipping candidate capture\",", "            article_id=article_id,", "            activity_id=activity_id,", "            exc_class=type(exc).__name__,", "            _exc=exc,", "        )", "", "", "async def match_location_to_master(", "    db: AsyncSession,", "    master_db: AsyncSession,", "    location: LocationSchema,", "    article_id: UUID,", "    activity_id: UUID | None = None,", ") -> List[IndustryRef]:", "    \"\"\"Build a location match map and create matched entities for industry refs.", "", "    :param db: Datalake database session (datalake_db).", "    :type db: AsyncSession", "    :param master_db: Master database session (master_db) for read-only lookups.", "    :type master_db: AsyncSession", "    :param location: :class:`LocationSchema` to match.", "    :type location: LocationSchema", "    :param article_id: The associated article ID.", "    :type article_id: UUID", "    :param activity_id: EC layer-one activity UUID for scoping matched_entity rows.", "    :type activity_id: UUID | None", "    :return: Industry refs derived from master matches.", "    :rtype: List[IndustryRef]", "    \"\"\"", "    match_map = await build_location_match_map(master_db, location)", "    if not match_map:", "        return []", "", "    return await collect_location_industry_refs(db, master_db, match_map, article_id, activity_id)", "", "", "async def build_location_match_map(", "    master_db: AsyncSession, location: LocationSchema", ") -> dict[tuple[int, int, int], dict]:", "    \"\"\"Build a mapping of master matches for a :class:`LocationSchema`.", "", "    Uses batch query to fetch all candidate matches in a single DB round-trip.", "", "    :param master_db: Master database session (master_db) for read-only lookups.", "    :type master_db: AsyncSession", "    :param location: Location entity to build candidates from.", "    :type location: LocationSchema", "    :return: Mapping of unique match keys to match details.", "    :rtype: dict[tuple[int, int, int], dict]", "    \"\"\"", "    # 1). Build candidate strings from the location (e.g. city, state, \"city state\", etc.)", "    candidates = build_location_match_candidates(location)", "    if not candidates:", "        return {}", "", "    # 2). Batch-fetch master text matches for all candidates in a single query", "    matches_by_text = await get_master_text_matches_batch(master_db, candidates)", "", "    # 3). Build deduplicated match map keyed by (master_text_id, entity_id, category_id).", "    #     Multiple candidates can match the same entity \u2014 only keep the first occurrence.", "    #     Every match is kept; a candidate resolving to multiple distinct corps is not", "    #     collapsed or skipped.", "    match_map: dict[tuple[int, int, int], dict] = {}", "    for candidate in candidates:", "        normalized = normalize_entity_text(candidate)", "        candidate_matches = matches_by_text.get(normalized, [])", "        for match in candidate_matches:", "            key = (", "                match[\"master_text\"].id,", "                match[\"xref\"].entity_id,", "                match[\"xref\"].category_id,", "            )", "            if key not in match_map:", "                match_map[key] = {\"match\": match, \"candidate\": candidate}", "", "    logger.info(", "        \"Location match candidates\",", "        candidate_count=len(candidates),", "        match_count=len(match_map),", "        city=location.place.city,", "        region=location.place.region,", "        state=location.place.state.value if location.place.state else None,", "    )", "", "    return match_map", "", "", "async def collect_location_industry_refs(", "    db: AsyncSession,", "    master_db: AsyncSession,", "    match_map: dict[tuple[int, int, int], dict],", "    article_id: UUID,", "    activity_id: UUID | None = None,", ") -> List[IndustryRef]:", "    \"\"\"Convert match map entries into industry refs by creating matched entities.", "", "    Batch-fetches context IDs and source map IDs for all entity_ids in the match map,", "    then creates matched_entity rows from the pre-fetched data. These rows are", "    location/industry-derivation records (they feed the returned industry refs), NOT", "    organization matches, so they are never CVW-stamped \u2014 only org matches", "    (``process_organizations_batch``) carry a CVW ``platform_entity_id``. The derived", "    ``ArticleIndustry`` rows get their own IVW stamp in ``write_matched_industries``.", "", "    :param db: Datalake database session (datalake_db).", "    :type db: AsyncSession", "    :param master_db: Master database session (master_db) for read-only lookups.", "    :type master_db: AsyncSession", "    :param match_map: Match map from build_location_match_map.", "    :type match_map: dict[tuple[int, int, int], dict]", "    :param article_id: The associated article ID.", "    :type article_id: UUID", "    :param activity_id: EC layer-one activity UUID for scoping matched_entity rows.", "    :type activity_id: UUID | None", "    :return: Industry refs for matched locations.", "    :rtype: List[IndustryRef]", "    \"\"\"", "    if not match_map:", "        return []", "", "    # 1). Batch-fetch context IDs and source map IDs for all entity_ids in the match map,", "    #     then release the master read BEFORE the datalake create_matched_entity writes so no", "    #     AccessShareLock sits idle across a cross-DB write (expire_on_commit=False keeps the", "    #     loaded match_map ORM objects usable). rollback+re-raise leaves the shared session", "    #     clean so match_locations' per-location except can skip and continue the loop.", "    all_entity_ids: set[int] = {entry[\"match\"][\"xref\"].entity_id for entry in match_map.values()}", "    try:", "        context_ids = await get_entity_context_ids_batch(master_db, all_entity_ids)", "        source_map_ids = await get_entity_source_map_ids_batch(master_db, all_entity_ids)", "        await master_db.commit()", "    except Exception:", "        await master_db.rollback()", "        raise", "", "    # 2). Create matched entity rows and build industry refs using pre-fetched data", "    industry_refs: List[IndustryRef] = []", "    for entry in match_map.values():", "        match = entry[\"match\"]", "        normalized_text = normalize_entity_text(entry[\"candidate\"])", "        entity_id = match[\"xref\"].entity_id", "", "        # (a). Resolve category priority, falling back to default if not present in match", "        cat_priority = match.get(\"category_priority\")", "        if cat_priority is None:", "            cat_priority = entity_config.DEFAULT_CATEGORY_PRIORITY", "", "        entity_source_map_id = source_map_ids.get(entity_id)", "", "        # (b). Create the matched_entity row \u2014 platform_entity_id stays None: these are", "        # location/industry-derivation rows, not org matches, so they are never CVW-stamped.", "        me_row = await create_matched_entity(", "            db,", "            article_id,", "            match[\"master_text\"].id,", "            entity_id,", "            entity_source_map_id,", "            context_ids.get(entity_id),", "            cat_priority,", "            normalized_text,", "            NORMALIZATION_VERSION,", "            layer_one_activity_id=activity_id,", "            platform_entity_id=None,", "        )", "", "        # (c). Build industry ref payload for downstream industry matching", "        industry_refs.append(", "            {", "                \"matched_entity_id\": me_row.id,", "                \"master_text_id\": match[\"master_text\"].id,", "                \"category_id\": match[\"xref\"].category_id,", "                \"entity_id\": entity_id,", "                \"source_refs\": extract_source_refs(match[\"entity\"].original_id),", "            }", "        )", "", "    return industry_refs", "", "", "async def write_matched_industries(  # noqa: C901", "    db: AsyncSession,", "    master_db: AsyncSession,", "    accelerate_db: AsyncSession,", "    article_id: UUID,", "    industry_refs: List[IndustryRef],", "    activity_id: UUID | None = None,", ") -> List[ArticleIndustry]:", "    \"\"\"Resolve industries from refs and write ArticleIndustry rows.", "", "    Each ArticleIndustry row is stamped with ``platform_entity_id`` via", "    ``resolve_platform_entity_id_safe(AccountType.IVW, industry_id)`` against", "    accelerate. NULL when the canonical row isn't yet visible.", "", "    :param db: Datalake database session (datalake_db).", "    :type db: AsyncSession", "    :param master_db: Master database session (master_db) for read-only lookups.", "    :type master_db: AsyncSession", "    :param accelerate_db: Accelerate database session for platform_entity_id resolution.", "    :type accelerate_db: AsyncSession", "    :param article_id: The associated article ID.", "    :type article_id: UUID", "    :param industry_refs: Industry refs from matching steps.", "    :type industry_refs: List[IndustryRef]", "    :return: The created ArticleIndustry rows (empty list if none).", "    :rtype: List[ArticleIndustry]", "    \"\"\"", "    if not industry_refs:", "        return []", "", "    industry_ids: set[int] = set()", "    account_ids: set[int] = set()", "    for ref_entry in industry_refs:", "        for ref in ref_entry.get(\"source_refs\", []):", "            table = ref.get(\"table\")", "            value = ref.get(\"value\")", "            if table == \"ind_vw.industries\" and isinstance(value, int):", "                industry_ids.add(value)", "            elif table == \"ind_vw.accounts\" and isinstance(value, int):", "                account_ids.add(value)", "", "    industry_defs = await get_industry_defs(", "        master_db,", "        industry_ids=industry_ids,", "        account_ids=account_ids,", "    )", "    if not industry_defs:", "        return []", "", "    defs_by_industry: dict[int, list] = {}", "    defs_by_account: dict[int, list] = {}", "    for ind_def in industry_defs:", "        defs_by_industry.setdefault(ind_def.industry_id, []).append(ind_def)", "        defs_by_account.setdefault(ind_def.account_id, []).append(ind_def)", "", "    resolved_industry_ids = {ind_def.industry_id for ind_def in industry_defs}", "    industries = await get_industries(master_db, resolved_industry_ids)", "", "    industry_payloads: dict[int, dict] = {}", "    for ref_entry in industry_refs:", "        matched_entity_id = ref_entry[\"matched_entity_id\"]", "        for ref in ref_entry.get(\"source_refs\", []):", "            table = ref.get(\"table\")", "            value = ref.get(\"value\")", "            if table == \"ind_vw.industries\" and isinstance(value, int):", "                defs = defs_by_industry.get(value, [])", "            elif table == \"ind_vw.accounts\" and isinstance(value, int):", "                defs = defs_by_account.get(value, [])", "            else:", "                continue", "", "            for ind_def in defs:", "                payload = industry_payloads.setdefault(", "                    ind_def.industry_id,", "                    {\"matched_entities\": [], \"matched_entity_ids\": set()},", "                )", "                payload[\"matched_entities\"].append(", "                    {", "                        \"matched_entity_id\": str(matched_entity_id),", "                        \"entity_id\": ref_entry.get(\"entity_id\"),", "                        \"master_text_id\": ref_entry.get(\"master_text_id\"),", "                        \"category_id\": ref_entry.get(\"category_id\"),", "                    }", "                )", "                payload[\"matched_entity_ids\"].add(str(matched_entity_id))", "", "    rows: List[ArticleIndustry] = []", "    for industry_id, payload in industry_payloads.items():", "        industry = industries.get(industry_id)", "        if industry is None:", "            continue", "", "        # Resolve canonical platform_entity_id for this industry.", "        # A transient accelerate outage degrades to NULL-stamping (logged at", "        # warning) rather than failing the article.", "        platform_entity_id: UUID | None = await resolve_platform_entity_id_safe(", "            accelerate_db,", "            PlatformAccountType.IVW,", "            industry_id,", "            article_id=article_id,", "            entity_kind=\"IVW\",", "            logger=logger,", "        )", "", "        rows.append(", "            ArticleIndustry(", "                article_id=article_id,", "                industry_id=industry_id,", "                industry_name=industry.industry_name,", "                matched_entities=payload[\"matched_entities\"],", "                matched_entity_ids=sorted(payload[\"matched_entity_ids\"]),", "                layer_one_activity_id=activity_id,", "                platform_entity_id=platform_entity_id,", "            )", "        )", "", "    if rows:", "        logger.info(", "            \"Industry matches\",", "            match_count=len(rows),", "            industries=[(row.industry_id, row.industry_name) for row in rows],", "        )", "", "    await create_industry_rows(db, rows)", "    return rows"], "blocks": [{"start": 1, "end": 91, "label": "Imports and module setup"}, {"start": 92, "end": 148, "label": "def get_entities_response"}, {"start": 149, "end": 173, "label": "class _HasEntityText"}, {"start": 174, "end": 185, "label": "def _sort_priority"}, {"start": 186, "end": 244, "label": "def _dedupe_matches_by_normalized_name"}, {"start": 245, "end": 362, "label": "def match_people"}, {"start": 363, "end": 480, "label": "def match_orgs"}, {"start": 481, "end": 536, "label": "def match_locations"}, {"start": 537, "end": 654, "label": "def write_article_entity_map"}, {"start": 655, "end": 666, "label": "def _compose_person_name"}, {"start": 667, "end": 681, "label": "def _compose_location_name"}, {"start": 682, "end": 833, "label": "def assemble_and_write_org_context"}, {"start": 834, "end": 872, "label": "def write_org_context_failsafe"}, {"start": 873, "end": 900, "label": "def _candidate_geography"}, {"start": 901, "end": 978, "label": "def assemble_and_write_candidate_observations"}, {"start": 979, "end": 1014, "label": "def write_candidate_observations_failsafe"}, {"start": 1015, "end": 1043, "label": "def match_location_to_master"}, {"start": 1044, "end": 1094, "label": "def build_location_match_map"}, {"start": 1095, "end": 1184, "label": "def collect_location_industry_refs"}, {"start": 1185, "end": 1309, "label": "def write_matched_industries"}], "lineCount": 1309, "sha256": "96d467b3269260219ceaedebc923f6954f973a135cd801e6e7c2f6051138429c", "endsWithNewline": true});
